const result = $json.result || [];

const updates = result
  .filter(u => u.message)
  .map(u => {
    const m = u.message;

    let message_type = 'other';
    let content = null;
    let file_id = null;

    if (m.text) {
      message_type = 'text';
      content = m.text;
    } else if (m.voice) {
      message_type = 'voice';
      content = null;
      file_id = m.voice.file_id;
    } else if (m.audio) {
      message_type = 'audio';
      content = null;
      file_id = m.audio.file_id;
    }

    return {
      update_id: u.update_id,
      message_id: m.message_id,
      chat_id: m.chat?.id ?? null,
      user_id: m.from?.id ?? null,
      first_name: m.from?.first_name ?? null,
      last_name: m.from?.last_name ?? null,
      date: m.date,
      message_type,
      content,
      file_id,
    };
  })
  .filter(u => u.chat_id !== null);

if (!updates.length) {
  return [
    {
      json: {
        updates: [],
        max_update_id: null,
        next_offset: null,
      }
    }
  ];
}

const maxUpdateId = Math.max(...updates.map(u => u.update_id));

return [
  {
    json: {
      updates,
      max_update_id: maxUpdateId,
      next_offset: maxUpdateId + 1,
    }
  }
];

const updates = $json.updates || [];
const next_offset = $json.next_offset;
const max_update_id = $json.max_update_id;

return updates.map(u => ({
  json: {
    ...u,
    next_offset,
    max_update_id,
  }
}));
